import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const read = file => fs.readFileSync(path.join(root, file), 'utf8');
const site = JSON.parse(read('content/site.json'));
const articles = JSON.parse(read('content/articles.json'));
const cases = JSON.parse(read('content/cases.json'));
const resources = JSON.parse(read('content/resources.json'));
const pages = [];
const e = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const assets = {
  logo: 'images/690fb39289db11369b0c47f0_Authentia_Logo_Black.svg',
  white: 'images/690fb392c460b1548a24b023_Authentia_Logo_White.svg',
  icon: 'images/690fb392c289e94b55cc62c3_Authentia_Logo_Icon_Dark.svg',
  reception: 'images/690fb3924111b4c3f7441ced_Authentia_Reception.jpg',
  man: 'images/691010365e39aa2958c73ca6_Authentia_Man_on_street.jpg',
  couch: 'images/690fb392d2ab543e33409cb3_Authentia_Woman_on_Couch.jpg',
  og: 'images/authentia-open-graph.jpg',
  heroPoster: 'images/690ed11d25c665792d57410e_6913707e77ef39304b965e13_Authentia_Hero_2-poster-00001.jpg'
};
const navItems = [['services.html','Services'],['case-studies.html','Our work'],['insights.html','Insights'],['resources.html','Resources'],['about.html','About']];
const origin = new URL(site.url).origin;
const publicPath = file => file === 'index.html' ? '/' : '/' + file.replace(/\.html$/, '');
const url = file => new URL(publicPath(file), origin).href;
const defaultModified = site.seo?.lastModified || '2026-10-28';
const validDate = value => typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value);
const analyticsPreferences = '<button type="button" class="hero-footer analytics-preferences" data-analytics-preferences>Analytics preferences</button>';
const prefix = file => file.includes('/') ? '../' : '';
function nav(file) {
  const p = prefix(file);
  return `<a class="skip-link" href="#main">Skip to content</a><header class="navbar site-navbar"><div class="navbar-logo-left-container shadow-three"><div class="container"><div class="navbar-wrapper"><a class="navbar-brand" href="${p}index.html" aria-label="Authentia home"><img class="image-3" src="${p}${assets.logo}" width="150" height="35" alt="Authentia"></a><button class="site-menu-toggle" type="button" aria-expanded="false" aria-controls="site-navigation" hidden>Menu</button><nav class="nav-menu-wrapper site-nav-menu" id="site-navigation" aria-label="Main navigation"><ul class="nav-menu-two w-list-unstyled">${navItems.map(([href,label]) => `<li><a class="nav-link" href="${p}${href}"${file === href || (href === 'services.html' && file.startsWith('services/')) || (href === 'case-studies.html' && file.startsWith('case-studies/')) || (href === 'insights.html' && file.startsWith('insights/')) || (href === 'resources.html' && file.startsWith('resources/')) ? ' aria-current="page"' : ''}>${label}</a></li>`).join('')}<li class="mobile-margin-top-10"><a class="nav-button w-button" href="${p}contact.html">Let’s talk</a></li></ul></nav></div></div></div></header>`;
}
function footer(file) {
  const p = prefix(file);
  return `<footer class="footer site-footer"><div class="container-9"><a href="${p}index.html" aria-label="Authentia home"><img class="image-5" src="${p}${assets.white}" width="340" height="80" alt="Authentia" loading="lazy"></a><p class="footer-note">Applied AI strategy and advisory.<br>Canada · United States · United Kingdom</p><nav class="footer-navigation" aria-label="Footer navigation">${[...navItems,['approach.html','Our approach'],['contact.html','Contact']].map(([href,label])=>`<a href="${p}${href}">${label}</a>`).join('')}</nav><div class="div-block-12"></div><div class="div-block-13"><a class="hero-footer" href="mailto:${site.email}">${site.email}</a><a class="hero-footer" href="${p}privacy.html">Privacy policy</a><a class="hero-footer" href="${p}terms.html">Terms of use</a>${file === '404.html' ? '' : analyticsPreferences}<p class="hero-footer">Authentia © 2026</p></div></div></footer>`;
}
function breadcrumbItems(file, title) {
  const items = [{name:'Home', file:'index.html', url:url('index.html')}];
  if (file === 'index.html') return items;
  const parent = [
    ['services/', 'services.html', 'Services'],
    ['case-studies/', 'case-studies.html', 'Our work'],
    ['insights/', 'insights.html', 'Insights'],
    ['resources/', 'resources.html', 'Resources']
  ].find(([directory]) => file.startsWith(directory));
  if (parent) items.push({name:parent[2], file:parent[1], url:url(parent[1])});
  const labels = {
    'services.html':'Services', 'case-studies.html':'Our work',
    'insights.html':'Insights', 'resources.html':'Resources',
    'about.html':'About Authentia', 'approach.html':'Our approach',
    'contact.html':'Contact', 'privacy.html':'Privacy policy',
    'terms.html':'Terms of use', '404.html':'Page not found'
  };
  items.push({name:labels[file] || title, file, url:url(file)});
  return items;
}
function breadcrumbs(file, title) {
  const items = breadcrumbItems(file, title);
  return `<nav class="breadcrumbs" aria-label="Breadcrumb"><ol>${items.map((item, index) => `<li>${index === items.length-1 ? `<span aria-current="page">${e(item.name)}</span>` : `<a href="${prefix(file)}${item.file}">${e(item.name)}</a>`}</li>`).join('')}</ol></nav>`;
}
function withBreadcrumbs(content, file, title) {
  // Keep the existing full-screen homepage hero intact.
  if (file === 'index.html') return content;
  const navigation = breadcrumbs(file, title);
  const marker = file === 'contact.html' ? '<div class="contact-parent">' : '<header class="page-hero"><div class="page-wrap">';
  if (!content.includes(marker)) throw new Error('Missing breadcrumb placement for '+file);
  return content.replace(marker, marker + navigation);
}
function pageGraph(file, title, description, schema, modified) {
  const canonical = url(file);
  const organizationId = origin + '/#organization';
  const websiteId = origin + '/#website';
  const webpageId = canonical + '#webpage';
  const breadcrumbId = canonical + '#breadcrumb';
  const organization = {
    '@type':'Organization', '@id':organizationId, name:site.name,
    url:origin+'/', email:site.email, logo:origin+'/'+assets.logo,
    description:'Applied AI strategy, implementation guidance and ongoing advisory for businesses in Canada, the United States and the United Kingdom.',
    areaServed:['CA','US','GB']
  };
  const website = {
    '@type':'WebSite', '@id':websiteId, url:origin+'/', name:site.name,
    publisher:{'@id':organizationId}, inLanguage:'en'
  };
  const breadcrumb = {
    '@type':'BreadcrumbList', '@id':breadcrumbId,
    itemListElement:breadcrumbItems(file, title).map((item,index) => ({
      '@type':'ListItem', position:index+1, name:item.name, item:item.url
    }))
  };
  let mainEntity = null;
  if (schema) {
    const {'@context':ignoredContext, ...provided} = schema;
    const entityType = provided['@type'];
    mainEntity = {...provided, '@id':canonical + (entityType === 'Service' ? '#service' : '#article')};
    if (entityType === 'Service') mainEntity.provider = {'@id':organizationId};
    if (entityType === 'Article') {
      mainEntity.author = {'@id':organizationId};
      mainEntity.publisher = {'@id':organizationId};
      mainEntity.mainEntityOfPage = {'@id':webpageId};
      mainEntity.inLanguage = 'en';
    }
  }
  const collectionFiles = ['services.html','case-studies.html','insights.html','resources.html'];
  const webpage = {
    '@type':collectionFiles.includes(file) ? 'CollectionPage' : 'WebPage',
    '@id':webpageId, url:canonical, name:title+' | '+site.name, description,
    isPartOf:{'@id':websiteId}, about:{'@id':organizationId},
    mainEntity:{'@id':mainEntity ? mainEntity['@id'] : organizationId}, inLanguage:'en'
  };
  if (file !== 'index.html') webpage.breadcrumb = {'@id':breadcrumbId};
  if (validDate(modified)) webpage.dateModified = modified;
  return {'@context':'https://schema.org', '@graph':[organization,website,...(file !== 'index.html'?[breadcrumb]:[]),webpage,...(mainEntity?[mainEntity]:[])]};
}
function analyticsScript(file) {
  const settings = site.analytics;
  if (file === '404.html' || !settings?.measurementId) return '';
  if (!/^G-[A-Z0-9]+$/.test(settings.measurementId) || !Array.isArray(settings.productionHosts)) {
    throw new Error('Invalid analytics configuration');
  }
  return `<script src="${prefix(file)}js/analytics.js" defer data-measurement-id="${e(settings.measurementId)}" data-production-hosts="${e(settings.productionHosts.join(','))}"></script>`;
}
function cleanLocalHtmlLinks(html, file) {
  return html.replace(/(\s)href=(["'])(.*?)\2/gi,(_,space,quote,href) => {
    if (!href || href.startsWith('#')) return `${space}href="${e(href)}"`;
    const resolved = new URL(href,origin+'/'+file);
    if (resolved.origin !== origin || !resolved.pathname.endsWith('.html')) {
      return `${space}href=${quote}${href}${quote}`;
    }
    const pathname = resolved.pathname.replace(/\/index\.html$/,'/').replace(/\.html$/,'');
    const destination = pathname+resolved.search+resolved.hash;
    return `${space}href="${e(/^(?:https?:)?\/\//i.test(href) ? origin+destination : destination)}"`;
  });
}
function writePage(file, title, description, content, {home=false, schema=null, modified=null, bodyClass='page-body', footerEnabled=true}={}) {
  const p = prefix(file);
  const notFound = file === '404.html';
  const reviewed = modified || schema?.dateModified || defaultModified;
  const data = notFound ? null : pageGraph(file,title,description,schema,reviewed);
  const graph = data ? `<script type="application/ld+json">${JSON.stringify(data).replace(/</g,'\\u003c')}</script>` : '';
  const canonical = notFound ? '' : `<link rel="canonical" href="${url(file)}">`;
  const robots = notFound ? 'noindex,follow' : 'index,follow,max-image-preview:large';
  const socialType = schema?.['@type'] === 'Article' ? 'article' : 'website';
  const socialImage = origin+'/'+assets.og;
  const socialAlt = 'Authentia — Applied AI strategy and consulting';
  const html = `<!DOCTYPE html>\n<html lang="en"${home?' data-wf-domain="authentia-6bfda6.webflow.io" data-wf-page="690ed11e25c665792d574115" data-wf-site="690ed11d25c665792d57410e"':''}><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">${notFound?'<base href="/">':''}<title>${e(title)} | Authentia</title><meta name="description" content="${e(description)}"><meta name="robots" content="${robots}">${canonical}<meta property="og:type" content="${socialType}"><meta property="og:site_name" content="Authentia"><meta property="og:title" content="${e(title)} | Authentia"><meta property="og:description" content="${e(description)}"><meta property="og:url" content="${url(file)}"><meta property="og:image" content="${socialImage}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="${e(socialAlt)}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${e(title)} | Authentia"><meta name="twitter:description" content="${e(description)}"><meta name="twitter:image" content="${socialImage}"><meta name="twitter:image:alt" content="${e(socialAlt)}"><meta name="theme-color" content="#f5f2ec">${home?`<link rel="preload" as="image" href="${p}${assets.heroPoster}" fetchpriority="high">`:''}<link rel="icon" href="${p}images/690fb2e13c2f2fbdff3fb669_Authentia_Favicon.png"><link rel="apple-touch-icon" href="${p}images/690fb2e6f5ba6801dcc84cb7_Authentia_Webclip.png"><link rel="stylesheet" href="${p}css/authentia-6bfda6.webflow.shared.4dbe70365.css"><link rel="stylesheet" href="${p}css/advisory.css"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter+Tight:wght@300;400;500;600;700&display=swap" rel="stylesheet">${home?'<script>document.documentElement.className += " w-mod-js";</script>':''}${graph}</head><body class="${bodyClass}">${nav(file)}${withBreadcrumbs(content,file,title)}${footerEnabled?footer(file):''}<script src="${p}js/advisory.js" defer></script>${analyticsScript(file)}${home?['jquery-3.5.1.min.dc5e7f18c8.js','webflow.schunk.a9f965304aa02a14.js','webflow.schunk.60a7136fef598b09.js','webflow.schunk.e58c313dddd7955d.js','webflow.7a34523a.fb9fdbfe6ad5a697.js','gsap.min.js','ScrollTrigger.min.js','SplitText.min.js'].map(src=>`<script src="js/${src}" defer></script>`).join(''):''}</body></html>\n`;
  fs.mkdirSync(path.dirname(path.join(root,file)),{recursive:true});
  fs.writeFileSync(path.join(root,file),cleanLocalHtmlLinks(html,file).replace(/></g, '>\n<'));
  pages.push({file,title,description,modified:reviewed});
}
const hero = (eyebrow,title,deck,meta='') => `<header class="page-hero"><div class="page-wrap"><p class="eyebrow">${eyebrow}</p><h1 class="page-title">${title}</h1><p class="page-deck">${deck}</p>${meta}</div></header>`;
const section = (body,theme='') => `<section class="page-section ${theme}"><div class="page-wrap">${body}</div></section>`;
const intro = (title,desc='') => `<div class="section-intro"><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>`;
const buttons = (label='Discuss your priorities',p='') => `<div class="button-row"><a class="main-button w-button" href="${p}contact.html">${label}</a><a class="text-link" href="${p}approach.html">How we work →</a></div>`;
const closing = (p='') => section(`<div class="split-layout"><div>${intro('A useful next conversation','Tell us what you are trying to improve, what you have already tried, and where a decision is getting stuck.')}</div><div>${buttons('Let’s talk',p)}</div></div>`,'light');
const card = (category,title,desc,href,label='Explore') => `<article class="editorial-card"><span class="eyebrow">${e(category)}</span><h3><a href="${href}">${e(title)}</a></h3><p>${e(desc)}</p><a class="text-link" href="${href}">${label} →</a></article>`;
const faq = items => `<div class="faq-list">${items.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;
const services = [
 {slug:'ai-strategy',title:'AI strategy and opportunity assessment',short:'Choose where to start',description:'Identify valuable use cases, test assumptions, and turn a broad AI ambition into a practical roadmap.',body:`<h2>Start with a business decision</h2><p>An AI strategy should help you decide where to invest, what to test, and what to leave alone. We start with the work your business needs to improve: a slow handoff, a knowledge bottleneck, a repetitive review, or a service experience that depends on scarce expertise.</p><p>Our role is to connect that operational context with realistic options. A useful recommendation considers your systems, the information available, the people who will use the solution, and the consequences when it gets something wrong.</p><h2>Find the opportunities worth investigating</h2><p>We work with leadership and the people closest to the workflow to understand how work happens today. What enters the process? Which decisions require judgement? Where do exceptions accumulate? Which steps create waiting, rework, or inconsistent output?</p><p>From there, we develop an opportunity shortlist. Each candidate needs an owner, a clear purpose, a plausible approach, and evidence that the problem matters. We assess value alongside feasibility and uncertainty, so an exciting idea does not outrank a more useful one simply because it is easier to demonstrate.</p><h2>What the engagement can cover</h2><ul><li>Leadership and workflow discovery to establish the problem and decision context.</li><li>An opportunity inventory with the assumptions and evidence behind each candidate.</li><li>Readiness review covering information quality, systems access, ownership, and adoption needs.</li><li>Build, buy, or adapt options, including the implications of existing tools.</li><li>A phased roadmap and a brief for the next pilot or procurement decision.</li></ul><h2>A roadmap your organisation can act on</h2><p>The output should be understandable to the executive sponsor and useful to the people responsible for implementation. We explain the recommendation, its trade-offs, dependencies, and open questions. Where evidence is weak, the next step may be a discovery task rather than a build.</p><p>A roadmap can include quick operational improvements as well as more ambitious projects. We make the relationship between them explicit: which early work creates knowledge, access, or habits that a later project will need?</p><h2>Decide what success would mean before the pilot</h2><p>We help define a baseline and the observations needed to judge the next step. Those might include the quality of an answer, the handling of exceptions, the time involved in a specific step, or whether people can use the workflow effectively. The right measures depend on the job the system is meant to do.</p><p>Expected benefits remain assumptions until tested. We make cost, volume, review effort, and adoption assumptions visible, and use ranges where a single forecast would suggest more certainty than the evidence supports.</p><h2>How we work with your team</h2><p>We agree a project scope around the decision you need to make. Your leadership provides sponsorship and context; workflow owners bring practical knowledge; technical colleagues contribute constraints and access requirements. Authentia brings structure, analysis, and recommendations across those perspectives.</p><p>You retain authority over priorities and investment. Your internal team or implementation partner can use the resulting brief to plan delivery, with Authentia available for continuing advice.</p><h2>A useful starting point</h2><p>Bring a business objective, one or two troublesome workflows, and any evidence you already have. You do not need a model preference or a finished project specification. If you want to prepare first, start with our <a href="../resources/ai-opportunity-scorecard.html">AI Opportunity Scorecard</a>.</p>`},
 {slug:'implementation-advisory',title:'Implementation and pilot advisory',short:'Guide the next step',description:'Shape a bounded pilot, evaluate tools and delivery plans, and help your team make informed implementation decisions.',body:`<h2>Carry the strategy into real decisions</h2><p>A promising use case introduces a new set of questions once a team starts planning implementation. Which capabilities should an existing product provide? What information should the system use? Where should a person review its output? What would justify expanding beyond a pilot?</p><p>Authentia supports the sponsor and delivery team through these decisions. We help translate the intended business outcome into a scope that a technical team or provider can assess, build, and evaluate.</p><h2>Give the pilot a clear job</h2><p>A pilot needs to resolve an uncertainty. It may test whether a product can use the right knowledge, whether a workflow fits daily operations, or whether review effort leaves a worthwhile benefit. Defining that purpose helps prevent a demonstration from becoming an open-ended implementation.</p><p>We help set the intended users, information sources, boundaries, and exceptions. A good pilot brief records what is included, what will wait, and what should happen when the proposed approach does not work.</p><h2>Make tool and provider choices in context</h2><p>We can help you develop evaluation questions, compare approaches, and review proposals against the workflow. A feature list is only part of that decision. Existing systems, access controls, knowledge maintenance, export options, running costs, and the team's ability to operate the solution all matter.</p><p>Where possible, evaluation should use representative work rather than an idealised demonstration. We help clarify which claims a provider needs to substantiate and which assumptions the client needs to test.</p><h2>Where we can contribute</h2><ul><li>A pilot charter with scope, intended users, dependencies, and decision criteria.</li><li>Tool and provider evaluation, with a record of trade-offs and open questions.</li><li>Workflow and integration planning alongside your technical colleagues.</li><li>Review of evaluation examples, escalation routes, and human review points.</li><li>Implementation briefings and decision support for the delivery team.</li><li>Results review and a recommendation to expand, revise, investigate, or stop.</li></ul><h2>Keep responsibilities visible</h2><p>In an advisory engagement, your team or implementation partner owns delivery and operation. We provide analysis, challenge, and guidance within an agreed scope. The sponsor owns business decisions, technical owners manage system access and implementation, and workflow owners help establish whether the change works in practice.</p><p>We make those responsibilities explicit at the beginning. Advice about a decision is useful when the people who must act on it know who is accountable for the next step.</p><h2>Review the whole workflow</h2><p>A technically convincing answer may still create work elsewhere. We look at how information arrives, how exceptions are resolved, how a person takes over, and how changes to the underlying business process reach the system. Training and knowledge maintenance belong in that conversation.</p><p>We also help distinguish a correctable implementation issue from a poor fit for the problem. A pilot can produce useful evidence even when the recommendation is to change the approach.</p><h2>Experience behind the advice</h2><p>Our <a href="../case-studies/dental-technology-ai-pilot.html">dental technology case</a> describes an engagement that progressed from use-case definition and development to a limited live rollout in Canada. That hands-on experience informs the questions we bring to advisory work. Each new engagement has its own agreed responsibilities.</p><p>Use our <a href="../resources/pilot-readiness-checklist.html">Pilot Readiness Checklist</a> to identify the prerequisites you already have and the questions that still need an owner.</p>`},
 {slug:'ongoing-advisory',title:'Ongoing AI advisory',short:'Keep a clear direction',description:'A continuing advisory relationship for leaders navigating AI priorities, investment choices, implementation questions, and adoption.',body:`<h2>A consistent point of view as the work develops</h2><p>AI decisions rarely arrive in a neat sequence. A department proposes a new tool while another team is testing a workflow. A provider changes its product. A pilot reveals that the original problem needs a different approach. Leadership needs a way to connect those decisions to business priorities.</p><p>Ongoing advisory gives you continuity. Authentia works with your sponsor and relevant colleagues to review progress, challenge assumptions, and identify the decisions that need attention.</p><h2>Set a useful remit</h2><p>We begin by agreeing the purpose of the relationship: the business priorities it supports, the people involved, the decisions in scope, and a practical working cadence. The arrangement should fit the volume and complexity of decisions your organisation actually faces.</p><p>A retainer can complement a focused strategy project or support work already underway. We agree capacity, availability, deliverables, and responsibilities in the engagement scope.</p><h2>What we can help with</h2><ul><li>Reviewing new AI opportunities against an existing roadmap.</li><li>Preparing leadership discussions and investment decision briefs.</li><li>Assessing tool proposals and questions from implementation partners.</li><li>Reviewing pilot findings, adoption challenges, and emerging dependencies.</li><li>Helping teams establish practical guidance for using AI in defined workflows.</li><li>Keeping a decision record so the reasoning behind choices remains visible.</li></ul><h2>Maintain a decision rhythm</h2><p>A useful review starts with what has changed. What evidence arrived? Which assumption failed? What is blocked? Which decision would allow the next piece of work to move? We use that context to keep conversations focused and prepare clear next steps.</p><p>Between reviews, agreed advisory work can include examining a proposal, helping shape a brief, or working through an implementation question with the relevant team. The scope determines the level of involvement.</p><h2>Connect leadership and delivery</h2><p>Executives need to understand the value, cost, risk, and organisational implications of a choice. Delivery teams need specific requirements, decisions, and access to people who understand the workflow. We help translate between these perspectives and surface unresolved assumptions.</p><p>The aim is to leave your organisation with clearer decisions and stronger internal capability. Recommendations should be understandable and reusable, with a record of the evidence and reasoning behind them.</p><h2>Adapt the roadmap as evidence improves</h2><p>A roadmap is a set of choices made with the information available at the time. As projects progress, some opportunities will deserve more investment, others may need preparation, and some may cease to be worthwhile. We help review those changes without treating the original plan as a fixed commitment.</p><p>We can also help you identify patterns across projects: repeated data problems, unclear ownership, duplicated tools, or training needs that deserve a shared response.</p><h2>Agree where advice ends and delivery begins</h2><p>Your organisation retains responsibility for implementation, deployment, procurement, and operation. Authentia supports those responsibilities through the agreed advisory remit. Where specialist technical, legal, or sector expertise is needed, we help make the question clear for the appropriate owner.</p><p>If you are deciding between a focused project and a retainer, start with the next few decisions you expect to make. We can recommend a scope around those needs and explain what continuing support would add.</p>`}
];

