writePage('resources.html','AI guides, templates and working packs','Free AI scorecards and templates, plus detailed strategy and pilot planning packs with practical prompts and editable worksheets.',`<main id="main">${hero('Resources','Practical tools.<br>Better decisions.','Free templates you can use today, alongside more substantial working packs for strategy and pilot planning.')}${section(`<div class="filter-bar" aria-label="Filter resources"><button class="filter-button" data-resource-filter="All" aria-pressed="true">All resources</button><button class="filter-button" data-resource-filter="Free" aria-pressed="false">Free downloads</button><button class="filter-button" data-resource-filter="Paid" aria-pressed="false">Paid packs</button></div><p class="result-count" data-resource-count aria-live="polite">${resources.length} resources</p><div class="content-grid">${resources.map(r=>`<div data-resource-kind="${e(r.kind)}">${card(r.kind==='Free'?'Free resource':'Paid working pack',r.title,r.description,'resources/'+r.slug+'.html',r.kind==='Free'?'Explore and download':'Explore the pack')}</div>`).join('')}</div>`)}${section(`<div class="prose" style="max-width:760px"><h2>Designed to produce something useful</h2><p>Each resource helps you prepare a brief, assess an opportunity, or structure a decision. Prompts include the context to provide and the checks to perform before acting on an output. Worked examples are fictional and clearly identified.</p><p>Free resources are available without an email address. Paid pack pages include public samples; contact us about purchasing a full pack while online checkout is being prepared.</p><h2>Prefer help applying the tools?</h2><p>A focused <a href="services/ai-strategy.html">strategy engagement</a> or <a href="services/ongoing-advisory.html">ongoing advisory relationship</a> can help you work through the decisions in your own business context.</p></div>`,'light')}${closing()}</main>`);
function resourceGuide(r) {
  const sourceFile = r.kind === 'Free'
    ? `downloads/free/${r.slug}/${r.slug}-guide.html`
    : path.posix.normalize(path.posix.join('resources',r.sample || ''));
  const permitted = r.kind === 'Free' ? 'downloads/free/' : 'downloads/samples/';
  if (!sourceFile.startsWith(permitted) || !sourceFile.endsWith('.html')) {
    throw new Error('Resource excerpt must come from a public guide or sample: '+r.slug);
  }
  const source = read(sourceFile);
  const match = source.match(/<\/header\s*>([\s\S]*?)<footer\b/i);
  if (!match) throw new Error('Missing public guide content for '+r.slug);
  let excerpt = match[1];
  if (r.kind === 'Paid') {
    excerpt = excerpt.replace(/<section\b[^>]*>\s*<h2\b[^>]*>\s*Next step\s*<\/h2>[\s\S]*?<\/section>/gi,'');
  }
  excerpt = excerpt.replace(/<(\/?)h([2-5])(\b[^>]*)>/gi,(_,closing,level,attributes) => `<${closing}h${Number(level)+1}${attributes}>`);
  // Resolve links as the standalone guide would, then use same-site root paths in the landing page.
  excerpt = excerpt.replace(/href=(["'])(.*?)\1/gi,(_,quote,href) => {
    if (!href || href.startsWith('#')) return `href="${e(href)}"`;
    const resolved = new URL(href,origin+'/'+sourceFile);
    if (resolved.origin !== origin) return `href="${e(href)}"`;
    return `href="${e(resolved.pathname+resolved.search+resolved.hash)}"`;
  });
  const title = r.kind === 'Free' ? 'Using this resource' : 'Read a sample';
  return `<section class="resource-guide" aria-labelledby="resource-guide-heading"><h2 id="resource-guide-heading">${title}</h2>${excerpt}</section>`;
}
for (const r of resources) {
  const checkout = site.products[r.slug]?.checkoutUrl;
  if (checkout && (!checkout.startsWith('https://') || !(new URL(checkout).hostname === 'lemonsqueezy.com' || new URL(checkout).hostname.endsWith('.lemonsqueezy.com')))) throw new Error('Unsupported checkout URL for '+r.slug);
  const purchase = r.kind==='Free'?`<a class="main-button w-button" href="${e(r.download)}" download>Download free resource</a>`:checkout?`<a class="main-button w-button" href="${e(checkout)}" data-resource-id="${e(r.slug)}">Buy the pack${site.products[r.slug]?.priceLabel?' · '+e(site.products[r.slug].priceLabel):''}</a>`:`<a class="main-button w-button" href="mailto:${site.email}?subject=${encodeURIComponent('Resource enquiry: '+r.title)}">Ask about this pack</a>`;
  const actions = `<div class="button-row">${purchase}${r.sample?`<a class="text-link" href="${e(r.sample)}">Read the free sample →</a>`:''}</div>`;
  writePage('resources/'+r.slug+'.html',r.title,r.description,`<main id="main">${hero('Resources · '+e(r.kind),e(r.title),e(r.description),`<div class="tag-row"><span class="tag">${e(r.kind)}</span><span class="tag">${r.kind==='Free'?'Guide + editable templates':'Guide + worksheets + prompts'}</span></div>${actions}`)}${section(`<div class="article-layout"><article class="prose">${r.body}${/<h2[^>]*>What is included<\/h2>/i.test(r.body)?'':`<h2>What is included</h2><ul>${r.contents.map(c=>`<li>${e(c)}</li>`).join('')}</ul>`}${resourceGuide(r)}${r.kind==='Paid'&&!checkout?'<p class="resource-status">Online checkout is being prepared. You can read the sample now and email us to discuss the full pack.</p>':''}${actions}</article><aside class="article-aside"><h2>Put it to work</h2><p>Use your own business context, record assumptions, and review AI-generated suggestions before acting.</p><a class="text-link" href="../resources.html">All resources →</a><p>Need a second perspective?</p><a class="text-link" href="../contact.html">Discuss advisory support →</a></aside></div>`)}${closing('../')}</main>`);
}

